import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
const median = (xs) => {
    const s = xs.filter(Number.isFinite).sort((a, b) => a - b);
    return !s.length ? NaN : s.length % 2 ? s[(s.length - 1) / 2] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2;
};
const LABEL = { A: "A full history", B: "B real compaction", C: "C compaction + ccp --recover", D: 'D fresh + "continue this task"', E: "E fresh + ccp --handoff" };
export async function writeReport(tasks, work, v, coverage) {
    const rows = (await readFile(join(work, "results.jsonl"), "utf8")).trim().split("\n").map((l) => JSON.parse(l));
    const prepared = JSON.parse(await readFile(join(work, "prepared.json"), "utf8"));
    const md = ["# Phase 8 results", "", `- Compiler \`${v.compiler}\` (tag context-compiler-v3), policy \`${v.policy}\`, effort medium`, "- Compaction summaries generated by the real Claude Code `/compact` on each scripted session", `- Date: ${new Date().toISOString()}`, ""];
    const conds = ["A", "B", "C", "D", "E"];
    md.push("## Summary", "", "| Condition | Runs | Success | Median turns | Median tokens in | Median tokens out | Median wall s | Wrong assumptions | Repeated failed approaches | Failed test runs | Clarifications | Unnecessary changes |", "|---|---|---|---|---|---|---|---|---|---|---|---|");
    for (const c of conds) {
        const R = rows.filter((r) => r.condition === c);
        if (!R.length)
            continue;
        md.push(`| ${LABEL[c]} | ${R.length} | ${R.filter((r) => r.success).length}/${R.length} | ${median(R.map((r) => r.turns ?? NaN))} | ${Math.round(median(R.map((r) => r.tokensIn)))} | ${Math.round(median(R.map((r) => r.tokensOut)))} | ${median(R.map((r) => r.wallSeconds)).toFixed(1)} | ${R.reduce((n, r) => n + r.wrongAssumptions, 0)} | ${R.reduce((n, r) => n + r.repeatedFailedApproaches, 0)} | ${R.reduce((n, r) => n + r.failedAttempts, 0)} | ${R.filter((r) => r.clarificationRequest).length} | ${R.filter((r) => r.unnecessaryChanges.length).length} |`);
    }
    md.push("", "## Per task", "", `| Task | ${conds.join(" | ")} | Failing hidden tests (by condition) |`, `|---|${conds.map(() => "---").join("|")}|---|`);
    for (const t of tasks) {
        const cell = (c) => rows.filter((r) => r.taskId === t.id && r.condition === c).map((r) => (r.success ? "✓" : "✗")).join(" ");
        const fails = conds.map((c) => {
            const f = [...new Set(rows.filter((r) => r.taskId === t.id && r.condition === c).flatMap((r) => r.failed))];
            return f.length ? `${c}: ${f.join("; ")}` : "";
        }).filter(Boolean).join(" · ");
        md.push(`| ${t.id} ${t.title} | ${conds.map(cell).join(" | ")} | ${fails.replace(/\|/g, "/")} |`);
    }
    md.push("", "## Fact coverage: real compaction summary vs ccp briefs", "", "| Task | Fact | Kind | In compaction summary | In --recover brief | In --handoff brief | Invented (summary/recover/handoff) |", "|---|---|---|---|---|---|---|");
    for (const t of tasks) {
        const p = prepared[t.id];
        if (!p)
            continue;
        for (const c of coverage(t, p)) {
            const yn = (b) => (b ? "✓" : "—");
            md.push(`| ${t.id} | ${c.name} | ${c.kind} | ${yn(c.inSummary)} | ${yn(c.inRecover)} | ${yn(c.inHandoff)} | ${c.kind === "unavailable" ? [c.invented.summary, c.invented.recover, c.invented.handoff].map((x) => (x ? "INVENTED" : "no")).join(" / ") : ""} |`);
        }
    }
    md.push("", "## Compiler latency", "");
    const lat = Object.values(prepared).flatMap((p) => [p.recover.latencyMs, p.handoff.latencyMs]);
    md.push(`- ${lat.length} briefs: median ${(median(lat) / 1000).toFixed(1)} s, min ${(Math.min(...lat) / 1000).toFixed(1)} s, max ${(Math.max(...lat) / 1000).toFixed(1)} s`);
    md.push("", "## Safety filter activity", "");
    for (const p of Object.values(prepared))
        for (const b of [p.recover, p.handoff]) {
            for (const l of b.neutralized)
                md.push(`- ${p.taskId}: withheld \`${l.slice(0, 140)}\``);
            for (const s of b.scrubbed)
                md.push(`- ${p.taskId}: scrubbed \`${s.slice(0, 140)}\``);
        }
    md.push("", "## Briefs and compaction summaries", "");
    for (const t of tasks) {
        const p = prepared[t.id];
        if (!p)
            continue;
        md.push(`### ${t.id} ${t.title}`, "", `Next message after compaction: \`${t.instruction}\``, "", "<details><summary>Real compaction summary</summary>", "", "```text", p.compactSummary, "```", "</details>", "", "**ccp --recover**", "", "```text", p.recover.text, "```", "", "**ccp --handoff**", "", "```text", p.handoff.text, "```", "");
    }
    await writeFile("docs/evaluation/phase8-results.md", md.join("\n"));
    await writeFile("docs/evaluation/phase8-results.json", JSON.stringify({ rows: rows.map(({ finalText: _f, ...r }) => r), prepared }, null, 2));
    console.log("report: docs/evaluation/phase8-results.md");
}
